"""Strict CSV-to-JSON library and command-line tool."""

from __future__ import annotations

import csv
import io
import json
import sys
from typing import Any


_HEADER = ["name", "note"]
_REQUIRED_KEYS = frozenset(_HEADER)


def _parse_rows(text: str) -> list[list[str]]:
    """Parse CSV using a small strict state machine.

    Unlike the standard csv reader, this rejects quotes appearing inside an
    unquoted field and rejects any character after a closing quote other than
    a delimiter, record terminator, or end of input.
    """
    if not isinstance(text, str):
        raise ValueError("CSV input must be a string")
    if not text:
        return []

    rows: list[list[str]] = []
    row: list[str] = []
    field: list[str] = []
    state = "start"
    index = 0
    ended_with_record_terminator = False

    def finish_field() -> None:
        row.append("".join(field))
        field.clear()

    def finish_row() -> None:
        finish_field()
        rows.append(row.copy())
        row.clear()

    while index < len(text):
        char = text[index]

        if state == "quoted":
            if char == '"':
                if index + 1 < len(text) and text[index + 1] == '"':
                    field.append('"')
                    index += 2
                    continue
                state = "after_quote"
            else:
                field.append(char)
            index += 1
            ended_with_record_terminator = False
            continue

        if state == "after_quote":
            if char == ",":
                finish_field()
                state = "start"
                ended_with_record_terminator = False
                index += 1
                continue
            if char == "\r" or char == "\n":
                finish_row()
                state = "start"
                ended_with_record_terminator = True
                if char == "\r" and index + 1 < len(text) and text[index + 1] == "\n":
                    index += 2
                else:
                    index += 1
                continue
            raise ValueError(
                f"malformed CSV: unexpected character after closing quote at position {index}"
            )

        if state == "start":
            if char == '"':
                state = "quoted"
                ended_with_record_terminator = False
                index += 1
                continue
            if char == ",":
                finish_field()
                ended_with_record_terminator = False
                index += 1
                continue
            if char == "\r" or char == "\n":
                finish_row()
                ended_with_record_terminator = True
                if char == "\r" and index + 1 < len(text) and text[index + 1] == "\n":
                    index += 2
                else:
                    index += 1
                continue
            field.append(char)
            state = "unquoted"
            ended_with_record_terminator = False
            index += 1
            continue

        # Unquoted field.
        if char == '"':
            raise ValueError(f"malformed CSV: quote in unquoted field at position {index}")
        if char == ",":
            finish_field()
            state = "start"
            ended_with_record_terminator = False
            index += 1
            continue
        if char == "\r" or char == "\n":
            finish_row()
            state = "start"
            ended_with_record_terminator = True
            if char == "\r" and index + 1 < len(text) and text[index + 1] == "\n":
                index += 2
            else:
                index += 1
            continue
        field.append(char)
        ended_with_record_terminator = False
        index += 1

    if state == "quoted":
        raise ValueError("malformed CSV: unterminated quoted field")
    if not ended_with_record_terminator:
        finish_row()
    return rows


def parse_records(text: str) -> list[dict[str, str]]:
    """Parse strict CSV with the required ``name,note`` header."""
    rows = _parse_rows(text)
    if not rows:
        raise ValueError("missing CSV header; expected name,note")
    if rows[0] != _HEADER:
        raise ValueError("invalid CSV header; expected exactly name,note")

    records: list[dict[str, str]] = []
    for line_number, row in enumerate(rows[1:], start=2):
        if len(row) != 2:
            raise ValueError(
                f"wrong column count on record {line_number}: expected 2, got {len(row)}"
            )
        records.append({"name": row[0], "note": row[1]})
    return records


def format_records(records: Any) -> str:
    """Serialize validated records as CSV using LF record terminators."""
    if isinstance(records, (str, bytes, bytearray, dict)):
        raise ValueError("records must be an iterable of dictionaries")
    try:
        iterator = iter(records)
    except TypeError as exc:
        raise ValueError("records must be an iterable of dictionaries") from exc

    validated: list[dict[str, str]] = []
    for index, record in enumerate(iterator):
        if not isinstance(record, dict):
            raise ValueError(f"record {index} must be a dictionary")
        try:
            keys_are_exact = record.keys() == _REQUIRED_KEYS
        except (TypeError, AttributeError):
            keys_are_exact = False
        if not keys_are_exact:
            raise ValueError(f"record {index} must contain exactly name and note")
        if not isinstance(record["name"], str) or not isinstance(record["note"], str):
            raise ValueError(f"record {index} values must be strings")
        validated.append(record)

    output = io.StringIO(newline="")
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(_HEADER)
    for record in validated:
        writer.writerow([record["name"], record["note"]])
    return output.getvalue()


def to_json(text: str) -> str:
    """Convert valid input CSV to JSON without ASCII-escaping Unicode."""
    return json.dumps(parse_records(text), ensure_ascii=False)


def main() -> int:
    """Run the command-line interface."""
    try:
        result = to_json(sys.stdin.read())
    except ValueError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 2
    sys.stdout.write(result)
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
